import sys, math; sys.path.insert(0,'/tmp/fl'); from emb import PELICAN, EAGLE
BLUE='#1d2f6f'; WHITE='#fbfaf6'; GOLD='#c9a227'; RED='#a8322d'; PURPLE='#4b2a6b'; GREEN='#2f6b46'; BROWN='#5a3a1e'
def colorize(t,m):
    for k,v in m.items():
        t=t.replace(f'class="{k}"', f'fill="{v}"' if k!='gs' else f'stroke="{v}" fill="none"')
    return t
PELB64=''
def pelimg(cx,cy,w):
    h=w*1142/1301
    return f'<image x="{cx-w/2:.1f}" y="{cy-h/2:.1f}" width="{w:.1f}" height="{h:.1f}" href="data:image/png;base64,{PELB64}"/>'
EAGB64=''
def eagimg(cx,cy,w):
    h=w*1005/938
    return f'<image x="{cx-w/2:.1f}" y="{cy-h/2:.1f}" width="{w:.1f}" height="{h:.1f}" href="data:image/png;base64,{EAGB64}"/>'
def pel(x,y,s,body,eye,acc=GOLD): return f'<g transform="translate({x},{y}) scale({s})">'+colorize(PELICAN,{'b':body,'w':body,'k':acc,'e':eye,'r':RED,'n':acc})+'</g>'
def eag(x,y,s,col,eye): return f'<g transform="translate({x},{y}) scale({s})">'+colorize(EAGLE,{'g':col,'gs':col,'e':eye})+'</g>'
LISB64=''
LIS_W=494/637
def fleur(x,y,s,col=None):
    h=68*s; w=h*LIS_W
    return f'<use href="#lis" x="{x-w/2:.1f}" y="{y-h/2-2*s:.1f}" width="{w:.1f}" height="{h:.1f}"/>'
def star(cx,cy,r,col):
    p=[f"{cx+(r if i%2==0 else r*.4)*math.cos(math.radians(-90+i*36)):.2f},{cy+(r if i%2==0 else r*.4)*math.sin(math.radians(-90+i*36)):.2f}" for i in range(10)]
    return f'<polygon points="{" ".join(p)}" fill="{col}"/>'
def laurel(x,y,r,col):
    out=[]
    for side in (-1,1):
        a0,a1=(118,245) if side<0 else (62,-65)
        for i in range(9):
            a=math.radians(a0+(a1-a0)*i/8.5); px,py=x+r*math.cos(a),y+r*math.sin(a); tang=math.degrees(a)+90
            for off in (40,-40):
                rot=tang+off; cx,cy=px+4.5*math.cos(math.radians(rot)),py+4.5*math.sin(math.radians(rot))
                out.append(f'<ellipse cx="{cx:.1f}" cy="{cy:.1f}" rx="6" ry="2.4" fill="{col}" transform="rotate({rot:.0f} {cx:.1f} {cy:.1f})"/>')
        sa,ea=math.radians(a0),math.radians(a1)
        out.append(f'<path d="M{x+r*math.cos(sa):.1f},{y+r*math.sin(sa):.1f} A{r},{r} 0 0 {1 if side<0 else 0} {x+r*math.cos(ea):.1f},{y+r*math.sin(ea):.1f}" fill="none" stroke="{col}" stroke-width="1.6"/>')
    return ''.join(out)
def crown(x,y,s,col=GOLD,gem=RED):
    return f'<g transform="translate({x},{y}) scale({s})" fill="{col}"><path d="M-20,8 L-23,-9 L-10,0 L0,-13 L10,0 L23,-9 L20,8Z"/><rect x="-21" y="8" width="42" height="6" rx="1"/><circle cx="-23" cy="-10" r="2.6"/><circle cx="0" cy="-14" r="2.6"/><circle cx="23" cy="-10" r="2.6"/><circle cx="0" cy="11" r="2" fill="{gem}"/></g>'
def bee(x,y,s,col=GOLD):
    return f'<g transform="translate({x},{y}) scale({s})" fill="{col}"><ellipse cx="-5.5" cy="-4" rx="5.5" ry="3"/><ellipse cx="5.5" cy="-4" rx="5.5" ry="3"/><ellipse cx="0" cy="3" rx="3.4" ry="6.5"/><circle cx="0" cy="-5" r="2.6"/></g>'
def wave(y,col,w): return f'<path d="M0,{y} Q37.5,{y-9} 75,{y} T150,{y} T225,{y} T300,{y}" fill="none" stroke="{col}" stroke-width="{w}"/>'
def palm(x,y,s):
    tx,ty=x,y-70*s
    fr=''
    for a,l in ((205,40),(170,38),(235,30),(145,34),(-25,40),(10,38),(-55,30),(35,34)):
        cx=tx+l*s*0.5*math.cos(math.radians(a)); cy=ty+l*s*0.5*math.sin(math.radians(a))+6*s
        fr+=f'<ellipse cx="{cx:.1f}" cy="{cy:.1f}" rx="{l*s*0.5:.1f}" ry="{4*s:.1f}" fill="{GREEN}" transform="rotate({a} {cx:.1f} {cy:.1f})"/>'
    return f'<path d="M{x-3*s},{y} Q{x+8*s},{y-35*s} {x},{y-70*s}" stroke="{BROWN}" stroke-width="{6*s}" fill="none" stroke-linecap="round"/>'+fr+f'<circle cx="{tx}" cy="{ty+2*s}" r="{3.5*s}" fill="{BROWN}"/>'
P1B64=''
P2B64=''
def palmimg(cx,base,h,two=False):
    r=(593/664) if two else (329/451); w=h*r; b=P2B64 if two else P1B64
    return f'<image x="{cx-w/2:.1f}" y="{base-h:.1f}" width="{w:.1f}" height="{h:.1f}" href="data:image/png;base64,{b}"/>'
CRB64=''
def crownimg(cx,bottom,w):
    h=w*284/331
    return f'<image x="{cx-w/2:.1f}" y="{bottom-h:.1f}" width="{w:.1f}" height="{h:.1f}" href="data:image/png;base64,{CRB64}"/>'
CIB64=''
BEEB64=''
def crownimp(cx,bottom,w):
    h=w*903/900
    return f'<image x="{cx-w/2:.1f}" y="{bottom-h:.1f}" width="{w:.1f}" height="{h:.1f}" href="data:image/png;base64,{CIB64}"/>'
def beeimg(cx,cy,w):
    h=w*394/398
    return f'<use href="#bee" x="{cx-w/2:.1f}" y="{cy-h/2:.1f}" width="{w:.1f}" height="{h:.1f}"/>'
CHB64=''
def chainimg(cx,cy,w):
    h=w*160/2048
    return f'<image x="{cx-w/2:.1f}" y="{cy-h/2:.1f}" width="{w:.1f}" height="{h:.1f}" href="data:image/png;base64,{CHB64}"/>'
def ring_text(cx,cy,rt,rb,top,bot,col,fs=11.5,ls=1.2):
    # librsvg nie obsługuje textPath, więc każda litera osobno, obrócona po łuku
    import math
    from PIL import ImageFont
    fnt=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSerif-Bold.ttf',100)
    def wd(c): return fnt.getlength(c)*fs/100
    def place(txt,r,upper):
        ws=[wd(c)+ls for c in txt]; tot=sum(ws)-ls
        ang_tot=tot/r*180/math.pi
        out=[]; acc=0
        for c,w in zip(txt,ws):
            mid=acc+(w-ls)/2; acc+=w
            off=(mid/tot-0.5)*ang_tot if tot else 0
            if upper:
                a=270+off; rot=off
                x=cx+r*math.cos(math.radians(a)); y=cy+r*math.sin(math.radians(a))
            else:
                a=90-off; rot=-off
                x=cx+r*math.cos(math.radians(a)); y=cy+r*math.sin(math.radians(a))
            out.append(f'<text x="{x:.2f}" y="{y:.2f}" transform="rotate({rot:.2f} {x:.2f} {y:.2f})" text-anchor="middle">{c}</text>')
        return ''.join(out)
    st=f'font-family="DejaVu Serif" font-weight="bold" font-size="{fs}" fill="{col}"'
    return f'<g {st}>'+place(top,rt,True)+place(bot,rb+fs*0.72,False)+'</g>'
def chain(x1,x2,y,col):
    out=[];x=x1;mid=(x1+x2)/2
    while x<=x2:
        if abs(x-mid)>16: out.append(f'<rect x="{x-7}" y="{y-4}" width="14" height="8" rx="4" fill="none" stroke="{col}" stroke-width="2.6"/>')
        x+=11
    out.append(f'<path d="M{mid-14},{y} l6,-6 M{mid+14},{y} l-6,6" stroke="{col}" stroke-width="2.6"/>')
    return ''.join(out)
def anchor_hammer(x,y,col):
    return f'''<g transform="translate({x},{y})" fill="{col}"><g transform="rotate(-32)"><rect x="-3.5" y="-36" width="7" height="64" rx="1"/><circle cx="0" cy="-41" r="6.5" fill="none" stroke="{col}" stroke-width="4"/><rect x="-15" y="-26" width="30" height="6" rx="2"/><path d="M-26,16 Q0,42 26,16 L30,10 L24,26 Q0,48 -24,26 L-30,10Z"/></g><g transform="rotate(32)"><rect x="-3.5" y="-26" width="7" height="60" rx="2"/><path d="M-16,-40 L14,-40 L18,-30 L-16,-28Z"/></g></g>'''
def tobacco(x,y,s,col,vein):
    return f'<g transform="translate({x},{y}) scale({s})"><path d="M0,-36 C24,-22 24,18 0,36 C-24,18 -24,-22 0,-36Z" fill="{col}"/><path d="M0,-30 L0,40 M0,-14 L-11,-22 M0,-14 L11,-22 M0,2 L-14,-6 M0,2 L14,-6 M0,18 L-12,10 M0,18 L12,10" stroke="{vein}" stroke-width="2" fill="none" stroke-linecap="round"/></g>'
def svg(b):
    d=f'<defs><symbol id="lis" viewBox="0 0 494 637"><image width="494" height="637" href="data:image/png;base64,{LISB64}"/></symbol></defs>' if '#lis' in b else ''
    if '#bee' in b: d+=f'<defs><symbol id="bee" viewBox="0 0 398 394"><image width="398" height="394" href="data:image/png;base64,{BEEB64}"/></symbol></defs>'
    return f'<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 300 200" width="1536" height="1024">{d}{b}</svg>'
bands=f'<rect width="300" height="200" fill="{WHITE}"/><rect width="66" height="200" fill="{BLUE}"/><rect x="234" width="66" height="200" fill="{BLUE}"/>'
F={}
F['1_oligarchia']=svg(bands+''.join(fleur(33,y,.55,GOLD) for y in (48,103,158))+''.join(fleur(267,y,.55,GOLD) for y in (48,103,158))+pelimg(150,104,138))
F['2_demokracja']=svg(bands+''.join(star(150+60*math.cos(math.radians(a)),112+60*math.sin(math.radians(a)),6.5,GOLD) for a in range(-162,-10,19))+pelimg(150,116,104))
F['3_konsulat']=svg(bands+f'<rect x="66" width="5" height="200" fill="{GOLD}"/><rect x="229" width="5" height="200" fill="{GOLD}"/>'+laurel(150,104,64,GREEN)+eagimg(150,104,96))
F['4_cesarstwo']=svg(f'<rect width="300" height="200" fill="{PURPLE}"/>'+laurel(150,112,72,GOLD)+eagimg(150,114,92)+crownimp(150,50,50)+''.join(beeimg(x,y,30) for x,y in ((30,30),(270,30),(30,170),(270,170))))
sem=''.join(fleur(x,y,.36,GOLD) for x in range(25,300,42) for y in range(24,200,42) if not (100<x<200 and y<180))
F['5_burbonowie']=svg(f'<rect width="300" height="200" fill="{BLUE}"/>{sem}<path d="M108,52 L192,52 L192,118 Q192,162 150,176 Q108,162 108,118Z" fill="{WHITE}"/><path d="M108,52 L192,52 L192,118 Q192,162 150,176 Q108,162 108,118Z" fill="none" stroke="{GOLD}" stroke-width="3"/>'+pelimg(150,118,84)+crownimg(150,58,70))
F['6_wolna']=svg(f'<rect width="300" height="100" fill="{BLUE}"/><rect y="100" width="300" height="100" fill="{RED}"/>'+wave(100,WHITE,12)+palmimg(150,172,142)+ring_text(150,106,84,80,"NUL N'EST ESCLAVE","EN LOUISIANE",WHITE,fs=12.5,ls=1.6))
F['7_komuna']=svg(f'<rect width="300" height="200" fill="{RED}"/>'+laurel(150,100,66,WHITE)+anchor_hammer(150,98,WHITE)+wave(186,WHITE,5))
F['8_konfederacja']=svg(f'<rect width="300" height="100" fill="{WHITE}"/><rect y="100" width="300" height="100" fill="{RED}"/><rect width="76" height="200" fill="{BLUE}"/>'+star(38,64,16,WHITE)+star(38,136,16,WHITE)+pelimg(188,52,92)+tobacco(188,150,1.0,GOLD,RED))
